content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/* ========================================================================== */
/* BFUSION Benefits Realization Tracker                                      */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Main Container                                                            */
/* ========================================================================== */
.bfusion-brt-wrap {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  padding: 12px 16px;
  display: block;
}
/* ========================================================================== */
/* Layout Rows                                                               */
/* ========================================================================== */
.brt-row {
  margin-bottom: 12px;
}
.brt-row--kpis {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
/* ========================================================================== */
/* KPI Cards                                                                 */
/* ========================================================================== */
.brt-kpi {
  flex: 1 1 110px;
  min-width: 100px;
  max-width: 190px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: row;
  transition: box-shadow 0.2s ease;
}
.brt-kpi:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}
.brt-kpi__accent {
  width: 4px;
  flex-shrink: 0;
}
.brt-kpi__body {
  padding: 10px 12px;
  flex: 1;
  min-width: 0;
}
.brt-kpi__value {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 2px;
}
.brt-kpi__label {
  font-size: 11px;
  font-weight: 500;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.brt-kpi__sub {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  margin-top: 2px;
}
/* ========================================================================== */
/* Portfolio Realization Gauge                                               */
/* ========================================================================== */
.brt-gauge {
  background: var(--bf-bg, #FFFFFF);
  border-radius: 8px;
  padding: 12px 16px;
}
.brt-gauge__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}
.brt-gauge__title {
  font-size: 11px;
  font-weight: 600;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.brt-gauge__pct {
  font-size: 20px;
  font-weight: 700;
}
.brt-gauge__track {
  height: 14px;
  border-radius: 7px;
  background: var(--bf-surface-alt, #F4F5F7);
  overflow: hidden;
  margin-bottom: 6px;
}
.brt-gauge__fill {
  height: 100%;
  border-radius: 7px;
  transition: width 0.4s ease;
}
.brt-gauge__labels {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* Projects List                                                             */
/* ========================================================================== */
.brt-projects {
  background: var(--bf-bg, #FFFFFF);
  border-radius: 8px;
  padding: 12px 16px;
}
.brt-projects__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.brt-projects__title {
  font-size: 11px;
  font-weight: 600;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.brt-projects__legend {
  display: flex;
  gap: 12px;
}
.brt-legend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  color: var(--bf-muted, #667079);
}
.brt-legend__bar {
  width: 16px;
  height: 6px;
  border-radius: 3px;
  flex-shrink: 0;
}
/* ========================================================================== */
/* Individual Project Row                                                    */
/* ========================================================================== */
.brt-project {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  padding: 8px 12px;
  margin-bottom: 6px;
  cursor: pointer;
  transition: box-shadow 0.15s ease, border-color 0.15s ease;
}
.brt-project:hover {
  border-color: var(--bf-rule, #E5E7EB);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
}
.brt-project:last-child {
  margin-bottom: 0;
}
.brt-project__info {
  flex: 0 0 160px;
  min-width: 120px;
}
.brt-project__name {
  font-size: 12px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brt-project__meta {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  margin-top: 1px;
}
.brt-project__bars {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.brt-bar {
  display: flex;
  align-items: center;
  gap: 6px;
}
.brt-bar__track {
  flex: 1;
  height: 8px;
  border-radius: 4px;
  background: var(--bf-surface-alt, #F4F5F7);
  overflow: hidden;
}
.brt-bar__fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s ease;
}
.brt-bar__fill--planned {
  background: #3b82f6;
}
.brt-bar__fill--realized {
  background: #22c55e;
}
.brt-bar__value {
  font-size: 10px;
  font-weight: 600;
  color: var(--bf-muted, #667079);
  flex-shrink: 0;
  min-width: 36px;
  text-align: right;
}
.brt-project__rate {
  flex-shrink: 0;
  font-size: 16px;
  font-weight: 700;
  min-width: 48px;
  text-align: right;
}
.brt-project__cbr {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 600;
  min-width: 40px;
  text-align: right;
}
/* ========================================================================== */
/* Landing Page                                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
